package main

import "fmt"

type Logger struct{ prefix string }

func (l Logger) Log(msg string) string { return l.prefix + msg }

type Service struct {
	Logger // 嵌入：Log 方法被提升到 Service
}

func (s Service) Log(msg string) string { return "service:" + msg } // 遮蔽提升上来的 Log

func main() {
	svc := Service{Logger: Logger{prefix: "db "}}
	fmt.Println(svc.Log("hi"))
	fmt.Println(svc.Logger.Log("hi"))
}

package main

import "fmt"

// Speaker 只描述「会说话」这一件事
type Speaker interface {
	Speak() string
}

// Dog 没有 implements，方法集满足 Speaker 就自动实现
type Dog struct{}

func (Dog) Speak() string { return "汪汪" }

func main() {
	var s Speaker = Dog{}
	fmt.Println(s.Speak())
}

package main

import "fmt"

// 接口定义在使用方（main 这一侧）
type UserStore interface {
	Get(id int) string
}

// 提供方只管实现方法，不声明实现关系
type memoryStore struct{ users map[int]string }

func (m memoryStore) Get(id int) string { return m.users[id] }

func main() {
	var store UserStore = memoryStore{users: map[int]string{1: "tom"}}
	fmt.Println(store.Get(1))
}

package main

import (
	"errors"
	"fmt"
)

type ValidationError struct {
	Field string
	Code  int
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("字段 %s 校验失败，错误码 %d", e.Field, e.Code)
}

func main() {
	var err error = &ValidationError{Field: "age", Code: 400}
	var ve *ValidationError
	if errors.As(err, &ve) {
		fmt.Println(ve.Field, ve.Code)
	}
}

package main

import "fmt"

type Counter struct{ n int }

func (c Counter) Get() int { return c.n }

func (c *Counter) Add() { c.n++ }

type Getter interface {
	Get() int
}

func main() {
	c := &Counter{}
	c.Add()
	var g Getter = c // 只有 *Counter 满足 Getter
	fmt.Println(g.Get())
}

type Counter struct {
	n int
}

var c Counter // 零值就是可用的初始状态
c.n++
fmt.Println(c.n)

func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, 0, len(s))
	for _, v := range s {
		out = append(out, f(v))
	}
	return out
}

var names = Map([]int{1, 2}, func(i int) string { return fmt.Sprint(i) })

type Point struct{ X, Y int }

// Go 不支持运算符重载，只能写普通方法
func (p Point) +(q Point) Point {
	return Point{p.X + q.X, p.Y + q.Y}
}
